// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.sail.lmdb.LmdbAccessQuantityQuote.Evidence;
import org.eclipse.rdf4j.sail.lmdb.LmdbAccessQuantityQuote.Quantity;
import org.eclipse.rdf4j.sail.lmdb.LmdbAccessQuantityQuote.Scope;
import org.junit.jupiter.api.Test;

/** Access quantities retain their own domain independently of evidence and invocation counts. */
class LmdbAccessQuantityScopeTest {

	private static final long RESIDUAL = LmdbIndexAccessFeatures.of(3, 2);

	@Test
	void nativeAndPackedVisitsRetainTheirOwnIntervalDomains() {
		LmdbAccessQuantityQuote single = LmdbAccessQuantityQuote.nativeCandidate(
				LmdbIndexAccessFeatures.of(0, 0), 4D, 10D, 100D, 10D, 1, 1, 30D, 0, 0D);
		assertEquals(10D, single.visitedEntries().lower());
		assertEquals(10D, single.visitedEntries().point());
		assertEquals(30D, single.visitedEntries().upper());
		assertEquals(Evidence.MODEL, single.visitedEntries().evidence());

		for (double invocations : new double[] { 0D, 1D, 3D }) {
			LmdbAccessQuantityQuote repeated = LmdbAccessQuantityQuote.packed(
					LmdbIndexAccessFeatures.of(2, 2), 4D, Scope.CONTEXT_OUTPUT, 10D, invocations,
					false, null, false, "posc", "prefixScan");
			assertEquals(10D * invocations, repeated.visitedEntries().point());
			assertTrue(Double.isNaN(repeated.visitedEntries().lower()));
			assertTrue(Double.isNaN(repeated.visitedEntries().upper()));
		}
	}

	@Test
	void partialWorkKeepsPerInvocationCandidateAndContextualOutputSeparate() {
		LmdbAccessQuantityQuote quote = LmdbAccessQuantityQuote.packed(RESIDUAL, 40D, Scope.CONTEXT_OUTPUT,
				9D, 5D, true, LmdbPlanningCardinality.exact(6D, 0L), false, "posc", "prefixScan");

		assertEquals(Scope.CONTEXT_OUTPUT, quote.emittedRows().scope());
		assertEquals(40D, quote.emittedRows().point());
		assertEquals(Scope.PER_INVOCATION, quote.prefixPopulation().scope());
		assertEquals(6D, quote.prefixPopulation().point());
		assertEquals(Evidence.EXACT, quote.prefixPopulation().evidence());
		assertEquals(Scope.PER_INVOCATION, quote.candidateRowsPerInvocation().scope());
		assertEquals(9D, quote.candidateRowsPerInvocation().point());
		assertEquals(Evidence.MODEL, quote.candidateRowsPerInvocation().evidence());
		assertEquals(Scope.INVOCATION_TOTAL, quote.visitedEntries().scope());
		assertEquals(Evidence.UNKNOWN, quote.visitedEntries().evidence());
		assertTrue(Double.isNaN(quote.visitedEntries().point()));
		assertEquals(Evidence.UNKNOWN, quote.indexSeeks().evidence());
		assertTrue(Double.isNaN(quote.indexSeeks().point()));
		assertEquals(Scope.INVOCATION_TOTAL, quote.cursorOpens().scope());
		assertEquals(5D, quote.cursorOpens().point());
	}

	@Test
	void completeWorkScalesPerInvocationWithoutScalingComponentOutput() {
		LmdbAccessQuantityQuote quote = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				17D, Scope.COMPONENT_OUTPUT, 3D, 4D, false, null, false, "posc", "prefixScan");

		assertEquals(Scope.COMPONENT_OUTPUT, quote.emittedRows().scope());
		assertEquals(17D, quote.emittedRows().point());
		assertEquals(17D, quote.emittedRowsAcrossInvocations(false).point());
		assertEquals(Scope.INVOCATION_TOTAL, quote.emittedRowsAcrossInvocations(false).scope());
		assertEquals(3D, quote.candidateRowsPerInvocation().point());
		assertEquals(Scope.INVOCATION_TOTAL, quote.visitedEntries().scope());
		assertEquals(12D, quote.visitedEntries().point());
		assertEquals(4D, quote.indexSeeks().point());
		assertEquals(4D, quote.cursorOpens().point());
		assertEquals(Evidence.UNKNOWN, quote.prefixPopulation().evidence());
	}

	@Test
	void oneNativeInvocationCanIncludeMultipleSourcesAndContextScans() {
		LmdbAccessQuantityQuote quote = LmdbAccessQuantityQuote.nativeCandidate(RESIDUAL,
				4D, 10D, 100D, 10D, 2, 3, 300D, 1, 0.08D);

		assertEquals(Scope.SOURCE_POPULATION, quote.sourcePopulation().scope());
		assertEquals(100D, quote.sourcePopulation().point());
		assertEquals(Scope.PER_INVOCATION, quote.prefixPopulation().scope());
		assertEquals(10D, quote.prefixPopulation().point());
		assertEquals(Scope.PER_INVOCATION, quote.emittedRows().scope());
		assertEquals(4D, quote.emittedRows().point());
		assertEquals(Scope.PER_INVOCATION, quote.sourceRowsHighPerInvocation().scope());
		assertEquals(300D, quote.sourceRowsHighPerInvocation().point());
		assertEquals(Scope.INVOCATION_TOTAL, quote.visitedEntries().scope());
		assertEquals(10D, quote.visitedEntries().point());
		assertEquals(Scope.INVOCATION_TOTAL, quote.indexSeeks().scope());
		assertEquals(6.8D, quote.indexSeeks().point(), 1.0e-12D);
		assertEquals(1D, quote.invocations());
		assertEquals(2D, quote.sources());
		assertEquals(3D, quote.sourceScans());
	}

	@Test
	void zeroInvocationsDoNotChangeAnIsolatedFactorOrInventUnknownWork() {
		LmdbAccessQuantityQuote known = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				7D, Scope.FACTOR_OUTPUT, 9D, 0D, false, null, false, "posc", "prefixScan");
		assertEquals(Scope.FACTOR_OUTPUT, known.emittedRows().scope());
		assertEquals(7D, known.emittedRows().point());
		assertEquals(0D, known.emittedRowsAcrossInvocations(true).point());
		assertEquals(Evidence.UNKNOWN, known.emittedRowsAcrossInvocations(false).evidence());
		assertEquals(9D, known.candidateRowsPerInvocation().point());
		assertEquals(0D, known.visitedEntries().point());
		assertEquals(0D, known.indexSeeks().point());
		assertEquals(0D, known.cursorOpens().point());

		LmdbAccessQuantityQuote unknown = LmdbAccessQuantityQuote.packed(RESIDUAL,
				7D, Scope.FACTOR_OUTPUT, Double.NaN, 0D, true, null, false, "posc", "prefixScan");
		assertEquals(Evidence.UNKNOWN, unknown.candidateRowsPerInvocation().evidence());
		assertEquals(Evidence.UNKNOWN, unknown.visitedEntries().evidence());
		assertEquals(Evidence.UNKNOWN, unknown.indexSeeks().evidence());
		assertTrue(Double.isNaN(unknown.visitedEntries().point()));
		assertTrue(Double.isNaN(unknown.indexSeeks().point()));
		assertEquals(0D, unknown.cursorOpens().point());
	}

	@Test
	void factorOutputScalesOnlyWithInputProofAndContextOutputDoesNotRescale() {
		LmdbAccessQuantityQuote factor = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				7D, Scope.FACTOR_OUTPUT, 9D, 3D, false, null, false, "posc", "prefixScan");
		assertEquals(7D, factor.emittedRows().point());
		assertEquals(21D, factor.emittedRowsAcrossInvocations(true).point());
		assertEquals(Scope.INVOCATION_TOTAL, factor.emittedRowsAcrossInvocations(true).scope());
		assertTrue(Double.isNaN(factor.emittedRowsAcrossInvocations(false).point()));
		LmdbAccessQuantityQuote context = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				40D, Scope.CONTEXT_OUTPUT, 9D, 5D, false, null, false, "posc", "prefixScan");
		assertEquals(40D, context.emittedRowsAcrossInvocations(false).point());
		assertEquals(Scope.CONTEXT_OUTPUT, context.emittedRows().scope());
	}

	@Test
	void missingCandidateAndOverflowPreserveWorkUncertaintyAndSaturation() {
		LmdbAccessQuantityQuote missing = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				2D, Scope.CONTEXT_OUTPUT, Double.NaN, 3D, false, null, false, "posc", "prefixScan");
		assertEquals(Evidence.UNKNOWN, missing.candidateRowsPerInvocation().evidence());
		assertEquals(Evidence.UNKNOWN, missing.visitedEntries().evidence());
		assertTrue(Double.isNaN(missing.visitedEntries().point()));
		LmdbAccessQuantityQuote overflow = LmdbAccessQuantityQuote.packed(LmdbIndexAccessFeatures.of(2, 2),
				2D, Scope.CONTEXT_OUTPUT, Double.MAX_VALUE, 2D, false, null, false, "posc", "prefixScan");
		assertEquals(Double.MAX_VALUE, overflow.visitedEntries().point());
	}

	@Test
	void constructorsRejectAmountsInTheWrongDomain() {
		assertThrows(IllegalArgumentException.class, () -> LmdbAccessQuantityQuote.packed(RESIDUAL,
				4D, Scope.PER_INVOCATION, 6D, 1D, true, null, false, "posc", "prefixScan"));
		assertThrows(IllegalArgumentException.class,
				() -> new Quantity(0D, Double.NaN, Double.NaN, Evidence.UNKNOWN, Scope.PER_INVOCATION));
		LmdbAccessQuantityQuote quote = LmdbAccessQuantityQuote.packed(RESIDUAL,
				4D, Scope.CONTEXT_OUTPUT, 6D, 1D, true, null, false, "posc", "prefixScan");
		assertThrows(IllegalArgumentException.class,
				() -> new LmdbAccessQuantityQuote(quote.features(), quote.sourcePopulation(), quote.emittedRows(),
						quote.emittedRows(), quote.visitedEntries(), quote.cursorOpens(), quote.indexSeeks(),
						quote.invocations(), quote.sources(), quote.sourceScans(), quote.candidateRowsPerInvocation(),
						quote.sourceRowsHighPerInvocation(), quote.residualFields(), quote.indexName(),
						quote.accessMode()));
	}

	@Test
	void candidateFloorRequiresBothInputsInTheSameInvocationDomain() {
		assertEquals(97D, LmdbAccessQuantityQuote.candidateRows(1D, 97D));
		assertEquals(103D, LmdbAccessQuantityQuote.candidateRows(103D, 97D));
		assertEquals(0D, LmdbAccessQuantityQuote.candidateRows(0D, 0D));
		assertTrue(Double.isNaN(LmdbAccessQuantityQuote.candidateRows(1D, Double.NaN)));
		assertTrue(Double.isNaN(LmdbAccessQuantityQuote.candidateRows(Double.NaN, 97D)));
	}
}
